('d8aed6ae-b328-4656-a383-992a7bbfec5c'::uuid, '2f6d17fa-6bb9-41f5-91d9-1db9f64870a4'::uuid, 1, $u$تم! تم خواب، عتاب ، شباب۔ دل کی وہ کیفیت ہو جو دل تک ہی محدود رہ جانے والی ہے۔ تم! تم میرے فن سے بالاتر ہو شاید کیونکہ آج تک میں تمہیں ایک تحریر، ایک محفل اور ایک رمز میں نہیں کہہ سکا۔$u$, null),
('9855e012-7d86-49aa-a4c4-813b4e5e94ec'::uuid, '2f6d17fa-6bb9-41f5-91d9-1db9f64870a4'::uuid, 2, $u$تم! تم ایک حقیقت ہو جسے میں خواب کر بیٹھا ہوں۔ تم! تم ایک رات ہو جس کی ٹھنڈک سے مجھے روشنیوں کی کرنیں جلانے لگ گئی ہیں۔ تم! تم وہ خیال ہو جو اکثر فراغت میں مجھے مصروف رکھتا ہے اور تم ہی میری لاشعوری بھی ہو کیونکہ جب میں تمہیں سوچتا ہوں تو کچھ اور نہیں سوجھتا ۔ تم! تم وہ راستہ ہو جہاں موجود تو کئی مسافر ہیں پر شاید جو کسی کی منزل کا معین نہیں۔ تم وہ چراغ ہو جو رات بھر جلتا رہتا ہے پر دن ہوتے ہی بےمقصد ہو جاتا ہے۔ تم! تم سمندر کی لہر ہو جو دل کے ساحل پہ آ کٹتی ہے۔ تم! تم بادل ہو جو جذبوں کی سرحد پہ برسنے لگتا ہے کہ ہوا اسے اپنے ساتھ اڑا لے جاتی ہے۔ تم! تم قافلہ ہو جس کی بھیڑ میں یہ دل پرامن رہتا ہے۔ تم! اس طرح کی سیکڑوں تمسیلیں ہو جسے میں اپنے ہاتھوں سے لکھتا ہوں۔$u$, null),
('a5495a06-86d1-42b7-8fcf-ad3239927563'::uuid, '2f6d17fa-6bb9-41f5-91d9-1db9f64870a4'::uuid, 3, $u$سنو ! تم، تم ہو جاناں۔$u$, null),
